-- VSL Seed: Chapter 2.1 Ban Than (content_id=2)
USE vsl_learning;

INSERT INTO content_items (content_id, title, description, image_url, keywords, order_index) VALUES
-- Page 89
(2, 'Áo phông', '1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào áo và kéo nhẹ lên. 2. Tay phải giống chữ cái ngón tay "P", lòng bàn tay hướng xuống dưới, đặt trước ngực.', 'cells/cell_p0089_1.png', 'áo phông,quần áo,trang phục', 1),
(2, 'Áo len', '1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào áo và kéo nhẹ lên. 2. Hai tay giống số tự nhiên "1", lòng bàn tay hướng vào nhau, đầu ngón tay hướng về phía trước, ngón trỏ phải đặt chéo, chạm trên ngón trỏ trái, trước ngực, xoay đồng thời hai cổ tay lên xuống giống hành động đan len.', 'cells/cell_p0089_2.png', 'áo len,quần áo,trang phục', 2),
(2, 'Áo veston', 'Hai tay giống chữ cái ngón tay "C", lòng bàn tay hướng vào trong, đặt chạm vào giữa ngực, tay phải đặt trên tay trái, giữ nguyên tay trái, di chuyển tay phải lên trên gần cổ.', 'cells/cell_p0089_3.png', 'áo veston,quần áo,trang phục', 3),
(2, 'Áo dài', '1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào áo và kéo nhẹ lên. 2. Tay phải khép, hơi khum lại, lòng bàn tay hướng vào trong, đầu ngón tay hướng vào trong, đặt gần ngực, di chuyển tay xuống dưới đùi.', 'cells/cell_p0089_4.png', 'áo dài,quần áo,trang phục', 4),

-- Page 90
(2, 'Quần âu', '1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào quần và kéo nhẹ lên. 2. Ngón cái và ngón trỏ tay phải mở ra, lòng bàn tay hướng vào trong, đầu ngón tay hướng lên trên, đặt gần hai bên cạnh mũi, đưa tay xuống dưới đồng thời chạm hai ngón tay vào nhau.', 'cells/cell_p0090_1.png', 'quần âu,quần áo,trang phục', 5),
(2, 'Quần bò', '1. Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào quần và kéo nhẹ lên. 2. Hai tay giống chữ cái ngón tay "N", lòng bàn tay hướng vào nhau, đầu ngón tay hướng về phía trước, đặt song song, trước ngực, giữ nguyên cánh tay, gập cổ tay phải lên, gập cổ tay trái xuống và ngược lại.', 'cells/cell_p0090_2.png', 'quần bò,quần áo,trang phục', 6),
(2, 'Quần soóc', 'Tay phải khép lại, lòng bàn tay ngửa, đầu ngón tay hướng sang trái, đặt áp vào đùi, đưa tay sang phải.', 'cells/cell_p0090_3.png', 'quần soóc,quần áo,trang phục', 7),
(2, 'Guốc', '1. Tay trái khum lại, lòng bàn tay ngửa, đặt trước ngực. Tay phải khép, hơi khum lại, lòng bàn tay úp, đưa các đầu ngón tay phải vào trong tay trái. 2. Tay trái khép, lòng bàn tay úp, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải mở xoè, hơi khum lại, lòng bàn tay ngửa, di chuyển mạnh tay xuống dưới chạm vào mu bàn tay trái (2 lần).', 'cells/cell_p0090_4.png', 'guốc,giày dép,trang phục', 8),

-- Page 91
(2, 'Yếm', '1. Hai tay nắm, lòng bàn tay úp, đặt gần nhau, trước cổ, di chuyển đồng thời hai tay theo đường vòng cung ra sau gáy. 2. Hai tay mở xoè, lòng bàn tay hướng vào trong, đầu ngón tay hướng xuống dưới, đặt sát ngực, di chuyển đồng thời hai tay xuống phía dưới.', 'cells/cell_p0091_1.png', 'yếm,quần áo,trang phục', 9),
(2, 'Giày', '1. Tay trái khép, khum lại, lòng bàn tay ngửa, đặt trước ngực. Tay phải khép, lòng bàn tay úp, đưa các đầu ngón tay phải vào trong lòng bàn tay trái. 2. Hai tay làm giống động tác buộc dây giày, lòng bàn tay hướng vào trong, đưa đồng thời cả hai tay lên trên và về hai phía.', 'cells/cell_p0091_2.png', 'giày,giày dép,trang phục', 10),
(2, 'Dép', 'Tay trái khép, khum lại, lòng bàn tay ngửa, đặt trước ngực. Tay phải khép, lòng bàn tay úp, đưa các đầu ngón tay phải vào trong lòng bàn tay trái.', 'cells/cell_p0091_3.png', 'dép,giày dép,trang phục', 11),
(2, 'Tất', 'Tay trái giống chữ cái ngón tay "V", lòng bàn tay úp, đầu ngón tay hướng xuống dưới, đặt trước ngực. Tay phải nắm, ngón trỏ và ngón cái chụm lại, đặt chạm vào đầu ngón trỏ tay trái, di chuyển tay dọc lên trên ngón trỏ tay trái.', 'cells/cell_p0091_4.png', 'tất,giày dép,trang phục', 12),

-- Page 92
(2, 'Găng tay', 'Tay trái khép, lòng bàn tay hướng vào trong, đầu ngón tay hướng chếch sang phải, đặt trước ngực. Tay phải khép, nắm vào đầu các ngón tay trái, rồi vuốt dọc xuống cổ tay đồng thời các ngón tay trái xoè ra.', 'cells/cell_p0092_1.png', 'găng tay,phụ kiện,trang phục', 13),
(2, 'Nón', 'Hai tay khép, lòng bàn tay hướng vào nhau, đầu ngón tay hướng chếch sang hai bên, đặt gần hai bên trán, đưa đồng thời hai tay xuống dưới và về hai phía.', 'cells/cell_p0092_2.png', 'nón,phụ kiện,trang phục', 14),
(2, 'Mũ', 'Tay phải khép, khum lại, lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt áp vào đỉnh đầu.', 'cells/cell_p0092_3.png', 'mũ,phụ kiện,trang phục', 15),
(2, 'Mũ lưỡi trai', 'Tay phải khép, khum lại, lòng bàn tay hướng sang trái, đầu ngón tay hướng sang trái, đặt gần trán, đưa tay về phía trước đồng thời chụm các ngón tay lại.', 'cells/cell_p0092_4.png', 'mũ lưỡi trai,phụ kiện,trang phục', 16),

-- Page 93
(2, 'Kính', 'Tay phải nắm, ngón trỏ và ngón cái cong lại, giống chữ cái ngón tay "C", lòng bàn tay hướng sang trái, đặt áp vào mắt phải.', 'cells/cell_p0093_1.png', 'kính,phụ kiện', 17),
(2, 'Hoa tai', '1. Tay phải mở, ngón trỏ và ngón cái nắm nhẹ vào tai phải, ở vị trí đeo khuyên tai. 2. Tay phải giống chữ cái ngón tay "O", lòng bàn tay hướng sang trái, đặt bên phải, ngang tầm mắt, giữ nguyên cánh tay, mở xoè các ngón tay ra.', 'cells/cell_p0093_2.png', 'hoa tai,phụ kiện,trang sức', 18),
(2, 'Lược', 'Tay phải mở, khum lại, đặt chạm các đầu ngón tay vào bên phải đầu, di chuyển tay xuống dưới (2 lần).', 'cells/cell_p0093_3.png', 'lược,phụ kiện,đồ dùng', 19),
(2, 'Cặp tóc', 'Tay phải nắm, ngón trỏ và ngón cái duỗi thẳng, lòng bàn tay hướng sang trái, đặt chạm vào bên phải đầu, di chuyển tay lên trên và đồng thời ngón trỏ, ngón cái chụm lại.', 'cells/cell_p0093_4.png', 'cặp tóc,phụ kiện', 20),

-- Page 94
(2, 'Bàn chải', '1. Tay trái giống số tự nhiên "1", lòng bàn tay ngửa, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải nắm, ngón cái và ngón trỏ chụm vào nhau, đặt chạm vào góc ngón trỏ tay trái, di chuyển ra đầu ngón trỏ tay trái. 2. Tay phải giống số tự nhiên "1", lòng bàn tay hướng vào trong, đặt ngang miệng, di chuyển sang trái rồi sang phải (2 lần).', 'cells/cell_p0094_1.png', 'bàn chải,đồ dùng,vệ sinh', 21),
(2, 'Khăn mặt', '1. Hai tay giống số tự nhiên "1", lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt song song trước ngực, di chuyển đồng thời hai tay theo đường hình chữ nhật. 2. Tay phải khép, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, đặt gần trán, di chuyển một vòng quanh mặt, ngược chiều kim đồng hồ.', 'cells/cell_p0094_2.png', 'khăn mặt,đồ dùng,vệ sinh', 22),
(2, 'Chào', 'Tay phải khép, lòng bàn tay hướng về phía trước, đầu ngón tay hướng lên trên, đặt bên phải, ngang tầm với mặt, đưa nhẹ tay sang hai bên (lặp lại 1 – 2 lần).', 'cells/cell_p0094_3.png', 'chào,giao tiếp,xã hội', 23),
(2, 'Bạn', 'Hai tay khép, ngón cái mở ra, lòng bàn tay hướng vào nhau, đầu ngón tay trái hướng sang phải, đầu ngón tay phải hướng về trước, đặt trước ngực, tay phải ở trên tay trái, bắt hai tay vào nhau.', 'cells/cell_p0094_4.png', 'bạn,giao tiếp,xã hội', 24),

-- Page 95
(2, 'Tuổi', 'Tay trái nắm, lòng bàn tay hướng vào trong, đặt trước ngực. Tay phải khép, hơi khum lại, lòng bàn tay hướng ra ngoài, đầu ngón tay hướng chếch lên trên, đặt trên tay trái, giữ nguyên cánh tay, xoay cổ tay một vòng từ ngoài vào trong đồng thời nắm tay lại rồi chạm vào tay trái.', 'cells/cell_p0095_1.png', 'tuổi,giao tiếp,bản thân', 25),
(2, 'Tên là gì?', '1. Hai tay giống số tự nhiên "1", lòng bàn tay hướng vào nhau, đặt chéo ngón trỏ phải bên trên ngón trỏ trái, trước ngực, đưa ngón trỏ phải vào ngón trỏ trái (lặp lại 2 lần). 2. Tay phải giống số tự nhiên "1", lòng bàn tay hướng về phía trước, đầu ngón tay hướng lên trên, đặt trước ngực, giữ nguyên cánh tay, lắc cổ tay qua lại (lặp lại 2 lần).', 'cells/cell_p0095_2.png', 'tên,câu hỏi,giao tiếp', 26),
(2, 'Bao nhiêu?', 'Tay phải nắm, lòng bàn tay ngửa, đặt trước ngực, giữ nguyên cánh tay, mở xoè bàn tay ra (lặp lại 2 lần).', 'cells/cell_p0095_3.png', 'bao nhiêu,câu hỏi,giao tiếp', 27),
(2, 'Xin lỗi', 'Tay trái khép, lòng bàn tay ngửa, đầu ngón tay hướng chếch sang phải, đặt trước ngực. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng chếch sang trái, đặt các đầu ngón tay vào lòng bàn tay trái, đưa tay dọc trong lòng bàn tay trái (lặp lại 2 – 3 lần).', 'cells/cell_p0095_4.png', 'xin lỗi,giao tiếp,xã hội', 28),

-- Page 96
(2, 'Xin phép', 'Tay phải khép, lòng bàn tay ngửa, đầu ngón tay hướng về phía trước, đặt trước ngực, di chuyển tay áp vào giữa ngực, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên.', 'cells/cell_p0096_1.png', 'xin phép,giao tiếp,xã hội', 29),
(2, 'Ở đâu?', '1 + 2. Hai tay nắm, ngón cái duỗi thẳng, lòng bàn tay hướng xuống dưới, đặt trước ngực, đầu ngón cái tay phải đặt chéo trên đầu ngón cái tay trái, đưa nhẹ tay xuống dưới, sau đó đưa hai tay về hai phía đồng thời các ngón tay mở xoè ra, lòng bàn tay ngửa.', 'cells/cell_p0096_2.png', 'ở đâu,câu hỏi,giao tiếp', 30),
(2, 'Thế nào?', '1 + 2. Hai tay mở, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt song song, trước ngực, đưa nhẹ cả hai tay lên trên và về hai phía, đồng thời mở xoè các ngón tay ra, lòng bàn tay ngửa.', 'cells/cell_p0096_3.png', 'thế nào,câu hỏi,giao tiếp', 31),
(2, 'Vui', 'Hai tay khép, lòng bàn tay hướng vào trong, đầu ngón tay của hai tay chạm vào nhau, đặt sát ngực, đưa nhẹ đồng thời cả hai tay lên trên và về hai bên (lặp lại 2 lần).', 'cells/cell_p0096_4.png', 'vui,cảm xúc,giao tiếp', 32),

-- Page 97
(2, 'Buồn', 'Tay phải nắm, lòng bàn tay hướng vào trong, đặt áp vào giữa ngực, đưa tay phải xoay tròn theo chiều kim đồng hồ.', 'cells/cell_p0097_1.png', 'buồn,cảm xúc,giao tiếp', 33),
(2, 'Làm gì?', '1. Hai tay nắm, lòng bàn tay hướng vào trong, đặt trước ngực, tay phải đặt trên tay trái, di chuyển tay phải lên – xuống chạm vào tay trái (lặp lại 2 lần). 2. Tay phải giống số tự nhiên "1", lòng bàn tay hướng về phía trước, đầu ngón tay hướng lên trên, đặt trước ngực phải, giữ nguyên cánh tay, lắc cổ tay sang hai bên (lặp lại 2 – 3 lần).', 'cells/cell_p0097_2.png', 'làm gì,câu hỏi,giao tiếp', 34),
(2, 'Khoẻ', 'Hai tay nắm, lòng bàn tay hướng vào nhau, đặt ở hai bên, ngang tầm với vai, gập mạnh đồng thời cả hai tay vào trong và xuống dưới.', 'cells/cell_p0097_3.png', 'khoẻ,sức khoẻ,bản thân', 35),
(2, 'Yếu', 'Hai tay giống chữ cái ngón tay "Y", lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt song song trước ngực, di chuyển đồng thời hai tay theo đường vòng cung từ ngoài vào trong, đồng thời khuôn mặt thể hiện sự mệt mỏi.', 'cells/cell_p0097_4.png', 'yếu,sức khoẻ,bản thân', 36),

